begin;
do $$ declare u uuid; begin select m.user_id into u from public.workspace_members m join public.profiles p on p.id=m.user_id and p.workspace_id=m.workspace_id limit 1; perform set_config('request.jwt.claim.sub',u::text,true); perform set_config('request.jwt.claims',jsonb_build_object('sub',u,'role','authenticated')::text,true); end $$;
set local role authenticated;
do $$ declare w uuid; p uuid; p2 uuid; e uuid; o uuid; pending uuid; begin
 select private.current_workspace_id() into w;
 insert into public.products(workspace_id,name,cost,price,stock) values(w,'__reward_test__',40,100,30) returning id into p;
 insert into public.products(workspace_id,name,cost,price,stock) values(w,'__reward_test_box__',20,50,30) returning id into p2;
 perform public.create_confirmation_employee('__reward_employee__',5,'per_item');
 select id into e from public.confirmation_employees where workspace_id=w and name='__reward_employee__';
 insert into public.orders(workspace_id,client_name,phone,address,status,items,confirmation_employee_id,confirmation_bonus) values(w,'__reward_test__','','','Confirmed',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1,'unitPrice',110)),e,999) returning id into o;
 if (select confirmation_bonus from public.orders where id=o)<>15 or (select confirmation_extra_bonus from public.orders where id=o)<>10 then raise exception '100 base and 110 sale must earn 15, ignoring client reward'; end if;
 update public.products set price=120 where id=p;
 update public.orders set notes='Preserve earned reward',confirmation_bonus=999,confirmation_extra_bonus=999 where id=o;
 if (select confirmation_bonus from public.orders where id=o)<>15 or (select (confirmation_base_prices->>p::text)::numeric from public.orders where id=o)<>100 then raise exception 'Note or catalog price changed earned reward'; end if;
 update public.orders set status='Delivered' where id=o;
 if (select confirmation_bonus from public.orders where id=o)<>15 then raise exception 'FIFO metadata or delivery changed earned reward'; end if;
 update public.orders set items=jsonb_build_array(jsonb_build_object('productId',p,'quantity',2,'unitPrice',130)) where id=o;
 if (select confirmation_bonus from public.orders where id=o)<>30 or (select confirmation_extra_bonus from public.orders where id=o)<>20 then raise exception 'Material edit did not follow current product base price'; end if;
 update public.orders set items=jsonb_build_array(jsonb_build_object('productId',p,'quantity',2,'unitPrice',130),jsonb_build_object('productId',p2,'quantity',1,'unitPrice',40)) where id=o;
 if (select confirmation_bonus from public.orders where id=o)<>35 then raise exception 'Discounted lines reduced positive price rewards'; end if;
 insert into public.orders(workspace_id,client_name,phone,address,status,items,confirmation_employee_id) values(w,'__reward_pending__','','','New',jsonb_build_array(jsonb_build_object('productId',p,'quantity',1,'unitPrice',130)),e) returning id into pending;
 if (select confirmation_bonus from public.orders where id=pending)<>0 then raise exception 'Unconfirmed order earned a reward'; end if;
 update public.products set price=125 where id=p;
 update public.orders set status='Confirmed' where id=pending;
 if (select confirmation_bonus from public.orders where id=pending)<>10 then raise exception 'Confirmation did not use latest base price'; end if;
 update public.orders set confirmation_employee_id=null where id=pending;
 if (select confirmation_bonus from public.orders where id=pending)<>0 then raise exception 'Admin earned a reward'; end if;
end $$;
rollback;
